ALTER TABLE "PlantSpecies" ADD COLUMN "rarity" TEXT NOT NULL DEFAULT 'Common', ADD COLUMN "growthDuration" INTEGER NOT NULL DEFAULT 3600;
ALTER TABLE "Achievement" ADD COLUMN "bonusXp" INTEGER NOT NULL DEFAULT 10;
CREATE TABLE "Garden" ("userId" TEXT NOT NULL PRIMARY KEY, "activePlantId" TEXT UNIQUE, "bankedSeconds" INTEGER NOT NULL DEFAULT 0, "focusSeconds" INTEGER NOT NULL DEFAULT 0, "bonusXp" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "Garden_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE, CONSTRAINT "Garden_activePlantId_fkey" FOREIGN KEY ("activePlantId") REFERENCES "UserPlant"("id") ON DELETE SET NULL);
